                "seriesColors": [
                    "#9b5ff4",
                    "#3abdfa",
                    "#0d8e97",
                    "#e2a811",
                    "#e44273",
                    "#a9afda",
                    "#d8580f",
                    "#f88ddc",
                    "#159352",
                    "#9abe2d",
                    "#6574f3",
                    "#ff9297",
                    "#d14baf",
                    "#24c4c9",
                    "#bb6e04",
                    "#6ec641",
                    "#777daf",
                    "#ff9755",
                    "#698c07",
                    "#c69fff"
