                "label": "> primary | seriesByName(\"State\")",
                "value": "> primary | seriesByName(\"Circuits\")"
            }
        },
        "viz_card_02_drilldown_trigger": {
            "type": "splunk.rectangle",
            "eventHandlers": [
                {
                    "type": "drilldown.customUrl",
                    "options": {
                        "url": "/drilldown?origin=Circuit%20Availability&target=Monitoring%20-%20SD-WAN%20-%20Site%20Health%20Table"
